<template>
  <div class="p7-shell" :class="{ stage: emPalco }">
    <template v-if="!emPalco">
      <div class="p7-intro"><div><h5>🎤 Palco 7</h5><p>Escolha um repertório e leve suas cifras salvas para o palco.</p></div></div>
      <div class="p7-grid"><button v-for="r in repertorios" :key="r.id" class="p7-card" @click="iniciar(r.id)"><strong>{{ r.nome }}</strong><span>{{ r.quantidadeMusicas }} música(s)</span><b>INICIAR MODO PALCO →</b></button></div>
      <div v-if="!repertorios.length" class="p7-empty">Crie primeiro um repertório no <b>Seven Repertório</b>.</div>
    </template>
    <template v-else>
      <div class="stage-top">
        <div class="stage-left"><button class="exit-btn" @click="sair">✕ Sair</button><div class="stage-tools"><div class="layout-toggle" title="Layout da cifra"><button :class="{active:layoutColunas===1}" @click="layoutColunas=1">1 coluna</button><button :class="{active:layoutColunas===2}" @click="layoutColunas=2">2 colunas</button></div><button @click="fonte=Math.max(12,fonte-1)">A−</button><button @click="fonte=Math.min(30,fonte+1)">A+</button><button @click="toggleFull">⛶</button></div></div>
        <div class="stage-repertoire-badge"><small>REPERTÓRIO</small><strong><span>🎼</span>{{ repertorio.nome }}</strong></div>
        <div class="stage-right"><div class="header-search" @click.stop><span class="header-search-icon">⌕</span><input v-model="buscaMusica" type="search" autocomplete="off" placeholder="Buscar música ou cantor..." aria-label="Buscar por nome da música ou cantor" @focus="buscaFocada=true" @keydown.esc="fecharBusca"><button v-if="buscaMusica" class="header-search-clear" type="button" @click="buscaMusica='';buscaFocada=true" aria-label="Limpar busca">×</button><div v-if="buscaFocada && buscaMusica" class="header-search-results"><button v-for="item in resultadosBusca" :key="item.musica.id" @click="irBusca(item)"><span><b>{{ item.musica.musica }}</b><small>{{ item.musica.artista }}</small><em>🎼 {{ item.repertorio.nome }}</em></span><strong>{{ item.musica.tomEscolhido }}</strong></button><div v-if="!resultadosBusca.length" class="header-search-empty">Nenhuma música ou cantor encontrado.</div></div></div><button class="header-list" @click.stop="listaAberta=!listaAberta">🎵 Ver lista de músicas</button></div>
      </div>
      <div class="stage-song"><div><h2>{{ atual.musica }}</h2><p>{{ atual.artista }}</p></div><div class="stage-tone">TOM {{ atual.tomEscolhido }}</div></div>
      <div ref="scroll" class="stage-scroll" :class="{'duas-colunas':layoutColunas===2}"><template v-if="layoutColunas===2"><pre :style="{fontSize: fonte+'px'}">{{ cifraColunas[0] }}</pre><pre :style="{fontSize: fonte+'px'}">{{ cifraColunas[1] }}</pre></template><pre v-else :style="{fontSize: fonte+'px'}">{{ atual.cifraCompleta }}</pre></div>
      <div class="stage-bottom"><button :disabled="indice===0" @click="anterior">← ANTERIOR</button><div class="song-position">Música <strong>{{ indice+1 }}</strong> de <strong>{{ musicas.length }}</strong></div><button :disabled="indice===musicas.length-1" @click="proxima">PRÓXIMA →</button></div>
      <div v-if="listaAberta" ref="stageList" class="stage-list" @click.stop>
        <div class="list-head"><div><small>REPERTÓRIO</small><b>Escolha o repertório</b></div><button @click="listaAberta=false">×</button></div>
        <div class="rep-picker">
          <button class="rep-picker-trigger" :disabled="trocandoRepertorio" @click.stop="dropdownAberto=!dropdownAberto">
            <span><small>REPERTÓRIO PARA CONSULTAR</small><b>{{ repertorioPainel ? repertorioPainel.nome : repertorio.nome }}</b></span>
            <span class="rep-count">{{ musicasPainel.length }} música(s)</span>
            <span class="rep-arrow" :class="{open:dropdownAberto}">⌄</span>
          </button>
          <div v-if="dropdownAberto" class="rep-picker-menu" @click.stop>
            <button v-for="r in repertorios" :key="r.id" :class="{selected:String(r.id)===String(repertorioPainel?.id)}" @click="selecionarRepertorioPainel(r.id)">
              <span><b>{{ r.nome }}</b><small>{{ r.quantidadeMusicas }} música(s)</small></span><strong v-if="String(r.id)===String(repertorioPainel?.id)">✓</strong>
            </button>
          </div>
        </div>
        <div class="list-summary"><b>{{ repertorioPainel ? repertorioPainel.nome : repertorio.nome }}</b><span>{{ musicasPainel.length }} música(s)</span></div>
        <button v-for="(musica, itemIndice) in musicasPainel" :key="musica.id" :class="{active:musicaPainelEstaNoPalco(musica)}" @click="irPainel(itemIndice)"><span>{{ itemIndice+1 }}</span><div><b>{{ musica.musica }}</b><small>{{ musica.artista }}</small></div><strong>{{ musica.tomEscolhido }}</strong></button>
        <div v-if="!musicasPainel.length" class="list-empty">Este repertório ainda não possui músicas.</div>
      </div>
    </template>
  </div>
</template>
<script>
import { listarRepertorios, obterRepertorio } from "../seven-repertorio/services/repertoriosService";
export default {
  name:"Palco7",
  data(){return{repertorios:[],repertoriosCompletos:[],repertorio:null,musicas:[],indice:0,emPalco:false,fonte:18,layoutColunas:1,listaAberta:false,trocandoRepertorio:false,repertorioPainel:null,musicasPainel:[],dropdownAberto:false,buscaMusica:"",buscaFocada:false}},
  computed:{
    atual(){return this.musicas[this.indice]||{}},
    resultadosBusca(){
      const termo=this.normalizarBusca(this.buscaMusica);
      if(!termo)return[];
      return this.repertoriosCompletos.flatMap(rep=>(rep.musicas||[]).map((musica,indice)=>({musica,indice,repertorio:rep}))).filter(({musica})=>this.normalizarBusca(musica?.musica).includes(termo)||this.normalizarBusca(musica?.artista).includes(termo)).slice(0,12);
    },
    cifraColunas(){
      const texto=this.atual.cifraCompleta||"";
      const linhas=texto.split("\n");
      if(linhas.length<2)return[texto,""];
      const meio=Math.ceil(linhas.length/2);
      let corte=meio;
      for(let d=0;d<=Math.min(12,linhas.length);d++){
        const antes=meio-d, depois=meio+d;
        if(antes>0&&antes<linhas.length&&!linhas[antes].trim()){corte=antes+1;break}
        if(depois>0&&depois<linhas.length&&!linhas[depois].trim()){corte=depois+1;break}
      }
      return[linhas.slice(0,corte).join("\n"),linhas.slice(corte).join("\n")];
    }
  },
  mounted(){this.carregar();document.addEventListener("click",this.fecharDropdownAoClicarFora)},
  beforeUnmount(){document.removeEventListener("click",this.fecharDropdownAoClicarFora)},
  methods:{
    normalizarBusca(valor){return String(valor||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().trim()},
    fecharDropdownAoClicarFora(event){if(this.dropdownAberto)this.dropdownAberto=false;if(this.buscaFocada)this.buscaFocada=false;if(this.listaAberta){const painel=this.$refs.stageList;if(painel && !painel.contains(event.target))this.listaAberta=false}},
    async carregar(){try{this.repertorios=await listarRepertorios();const completos=await Promise.all(this.repertorios.map(r=>obterRepertorio(r.id).catch(()=>null)));this.repertoriosCompletos=completos.filter(Boolean)}catch(e){this.erro(e)}},
    async iniciar(id){try{const r=this.repertoriosCompletos.find(x=>String(x.id)===String(id))||await obterRepertorio(id);if(!r.musicas?.length)return alert("Este repertório ainda não possui músicas.");this.repertorio=r;this.musicas=r.musicas;this.repertorioPainel=r;this.musicasPainel=r.musicas;this.indice=0;this.emPalco=true;this.$nextTick(()=>this.topo())}catch(e){this.erro(e)}},
    async selecionarRepertorioPainel(id){this.dropdownAberto=false;if(String(id)===String(this.repertorioPainel?.id))return;this.trocandoRepertorio=true;try{const r=await obterRepertorio(id);this.repertorioPainel=r;this.musicasPainel=r.musicas||[];}catch(e){this.erro(e)}finally{this.trocandoRepertorio=false}},
    musicaPainelEstaNoPalco(m){return String(this.repertorioPainel?.id)===String(this.repertorio?.id)&&String(m.id)===String(this.atual?.id)},
    sair(){this.emPalco=false;this.listaAberta=false;this.dropdownAberto=false;this.buscaMusica="";this.buscaFocada=false;this.repertorio=null;this.repertorioPainel=null;this.musicas=[];this.musicasPainel=[];this.carregar()},
    topo(){if(this.$refs.scroll)this.$refs.scroll.scrollTop=0},
    anterior(){if(this.indice>0){this.indice--;this.topo()}},
    proxima(){if(this.indice<this.musicas.length-1){this.indice++;this.topo()}},
    fecharBusca(){this.buscaFocada=false},
    irBusca(item){if(!item?.repertorio||!item?.musica)return;const rep=item.repertorio;const lista=rep.musicas||[];const i=lista.findIndex(m=>String(m.id)===String(item.musica.id));if(i<0)return;this.repertorio=rep;this.musicas=lista;this.indice=i;this.repertorioPainel=rep;this.musicasPainel=lista;this.dropdownAberto=false;this.buscaMusica="";this.buscaFocada=false;this.$nextTick(()=>this.topo())},
    irPainel(i){const m=this.musicasPainel[i];if(!m)return;this.repertorio=this.repertorioPainel;this.musicas=this.musicasPainel;this.indice=i;this.dropdownAberto=false;this.$nextTick(()=>this.topo())},
    toggleFull(){if(!document.fullscreenElement)this.$el.requestFullscreen?.();else document.exitFullscreen?.()},
    erro(e){console.error(e);alert(e.response?.data?.message||e.message||"Ocorreu um erro.")}
  }
};
</script>
<style scoped>
