verflow:ellipsis;text-shadow:0 1px 0 #000}.stage-repertoire-badge strong span{color:#8ed8ef}.stage-top .header-list{background:#20262d;border-color:#ff6c22;color:#fff;padding:8px 12px;white-space:nowrap}.stage-top .header-list:hover{background:#292f37}.stage-tools{display:flex;gap:6px;align-items:center}.layout-toggle{display:flex;border:1px solid #303944;border-radius:8px;overflow:hidden;background:#0d1115}.layout-toggle button{border:0!important;border-radius:0!important;background:transparent!important;color:#9da7b2!important;padding:8px 10px!important;min-width:auto!important}.layout-toggle button+button{border-left:1px solid #303944!important}.layout-toggle button.active{background:#ff6c22!important;color:#fff!important}.stage-song{padding:18px 26px 12px}.stage-song h2{font-size:24px;margin:0;color:#fff}.stage-song p{margin:4px 0 0;color:#aeb6c2}.stage-tone{background:#ff6c22;color:#fff;border-radius:8px;padding:9px 13px;font-weight:900}.stage-scroll{overflow:auto;padding:8px 34px 80px}.stage-scroll.duas-colunas{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:42px;align-items:start}.stage-scroll pre{margin:0;color:#f4f6f8;background:transparent;white-space:pre;font-family:"Courier New",monospace;line-height:1.35;overflow:visible}.stage-bottom{padding:12px 18px;background:#11161b;border-top:1px solid #252c34}.stage-bottom button{min-width:140px}.stage-bottom button:disabled{opacity:.3}.song-position{min-width:210px;text-align:center;color:#9da7b2;font-size:12px;letter-spacing:.02em}.song-position strong{color:#fff;font-size:13px}.stage-list{position:fixed;z-index:10001;top:0;bottom:0;right:0;width:min(420px,92vw);background:#11161b;border-left:1px solid #303944;padding:14px;overflow:auto;box-shadow:-20px 0 50px rgba(0,0,0,.4)}.list-head{display:flex;justify-content:space-between;align-items:center;padding:8px 4px 10px}.list-head>div{display:flex;flex-direction:column;gap:3px}.list-head small{font-size:10px;color:#7f8995;letter-spacing:.08em}.l