kground:#172a35}.header-search input:focus{border-color:#72d6f3;background:#19303d;box-shadow:0 0 0 3px rgba(70,185,220,.16)}.header-search input::placeholder{color:#a9c5cf;font-weight:600}.header-search-icon{position:absolute;z-index:2;left:11px;top:50%;transform:translateY(-50%);color:#7fdcf5;font-size:19px;font-weight:900;pointer-events:none}.header-search-clear{position:absolute;z-index:3;right:5px;top:50%;transform:translateY(-50%);width:27px!important;height:27px;display:flex!important;align-items:center!important;justify-content:center!important;background:transparent!important;border:0!important;color:#aeb6c2!important;font-size:18px!important;padding:0!important}.header-search-results{position:absolute;z-index:10005;right:0;top:calc(100% + 7px);width:min(390px,86vw);background:#11161b;border:1px solid #303944;border-radius:10px;padding:5px;box-shadow:0 16px 36px rgba(0,0,0,.55);max-height:360px;overflow:auto}.header-search-results>button{width:100%;display:flex;align-items:center;justify-content:space-between;gap:12px;background:transparent;border:0;border-radius:7px;padding:9px 10px;text-align:left;font-family:monospace}.header-search-results>button:hover{background:#1b222a}.header-search-results>button span{display:flex;flex-direction:column;min-width:0}.header-search-results>button b{color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.header-search-results>button small{color:#b6c0ca;margin-top:2px}.header-search-results>button em{color:#78cce6;margin-top:3px;font-size:9px;font-style:normal}.header-search-results>button strong{color:#ff8a4c}.header-search-empty{padding:16px;text-align:center;color:#9099a5;font-size:11px}.list-summary{display:flex;justify-content:space-between;align-items:center;color:#aeb6c2;padding:2px 4px 10px;font-size:11px}.list-summary b{color:#fff;font-size:12px}.list-empty{border:1px dashed #303944;border-radius:8px;padding:20px;text-align:center;color:#9099a5}.stage-list>button{width:100%;display:grid;grid-template-columns:32px 1fr 45px;gap:9px;align-items:center;text-align:left;background:#171d23;color:#fff;border:1px solid #282f38;border-radius:8px;padding:10px;margin-bottom:7px}.stage-list>button.active{border-color:#ff6c22}.stage-list small{display:block;color:#9099a5}.stage-list strong{color:#ff8a4c;text-align:right}@media(max-width:900px){.stage-repertoire-badge{position:static;transform:none;min-width:0;max-width:180px;padding:5px 10px}.stage-repertoire-badge strong{font-size:11px}.header-search{width:190px}.stage-top{padding:7px 9px}.exit-btn{margin-right:2px}}@media(max-width:600px){.stage-song{padding:14px}.stage-scroll{padding:5px 18px 70px}.stage-scroll.duas-colunas{grid-template-columns:1fr;gap:24px}.layout-toggle{display:none}.stage-bottom button{min-width:0;padding:9px}.stage-top{font-size:11px;flex-wrap:wrap}.stage-left,.stage-right{flex:1 1 auto}.stage-repertoire-badge{order:3;width:100%;max-width:none}.header-search{width:150px}.stage-top .header-list{padding:8px 9px;font-size:10px}.song-position{min-width:0}.stage-song h2{font-size:19px}}
